import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"34、【大壮】 乾下震上","description":"周易集注 - 34、【大壮】 乾下震上","frontmatter":{"title":"34、【大壮】 乾下震上","description":"周易集注 - 34、【大壮】 乾下震上"},"headers":[],"relativePath":"zh/classics/jizhu/038.md","filePath":"zh/classics/jizhu/038.md"}'),h={name:"zh/classics/jizhu/038.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_34、【大壮】-乾下震上" tabindex="-1">34、【大壮】 乾下震上 <a class="header-anchor" href="#_34、【大壮】-乾下震上" aria-label="Permalink to “34、【大壮】 乾下震上”">​</a></h1><p>大壮者，大者壮也。大谓阳也，四阳盛长，故为大壮，二月之卦也。为卦震上干下，乾刚而震动，大壮之义也。又雷之威震于天上，声势壮大，亦大壮之义也。《序卦》：“遁者退也，物不可以终遁，故受之以大壮。”遁者阳衰而遁也，壮者阳盛而壮。衰则必盛，消长循环之理，所以次遁。</p><p>阳壮则占者吉亨，不必言矣。然君子所谓壮者，非徒以其势之盛，乃其理之正也，故利于正。阴之进不正，则小人得以陵君子，故遁言小者利于贞。阳之进不正，则君子不能胜小人，故大壮言大者利于贞。大壮综遁，二卦本是一卦，故卦下之辞如此。</p><p>《彖》曰：大壮，大者壮也，刚以动故壮。大壮利贞，大者正也，正大而天地之情可见矣!</p><p>以卦体卦德释卦名，又释利贞之义而极言之。阳长过中，大者壮也。盖正月泰，阳虽长而未盛，三月夬，阳已盛而将衰，皆不可以言壮，惟四阳则壮矣。且乾刚震动，刚则能胜其人欲之私，动则能奋其必为之志，何事不可行哉，此其所以壮也。卦体则势壮，卦德则理壮，所以名壮。大者正也，言大者自无不正也。凡阳明则正，阴浊则邪，自然之理，故利于贞，若不贞则非大矣。正大者，正则无不大也。天地之情者，覆载生成所发之情也，一通一复，皆一诚之贯彻，岂不正?既正岂不大?故曰正大。盖大者壮，以气言，乃壮之本体也。大者正，以理言，所以运壮之道也。正大而天地之情可见，又推极上天下地，莫非此正大之理，非特人为然也。一阳来复，见天地之心，四阳见其情。仁者天地之心，情则其所发也。</p><h3 id="《象》曰-雷在天上-大壮-君子以非礼弗履。" tabindex="-1">《象》曰：雷在天上，大壮，君子以非礼弗履。 <a class="header-anchor" href="#《象》曰-雷在天上-大壮-君子以非礼弗履。" aria-label="Permalink to “《象》曰：雷在天上，大壮，君子以非礼弗履。”">​</a></h3><p>非礼者，人欲之私也。履者践履也，非礼弗履，则有以克胜其人欲之私矣，此惟刚健以动者可能。矫哉其强，何壮如之，雷在天上，大壮者，以声势而见其壮也。君子非礼弗履，大壮者以克胜其私，而见其壮也。</p><p>初九，壮于趾，征凶，有孚。</p><p>震为足，又初在下，趾之象也。征凶者，往则必裁抑摈斥也。孚者，自信其阳刚之正德也。初以阳居阳，干之刚未盛也，故有孚。至三则乾刚极矣，故贞厉。</p><p>初九，阳刚处下，当壮之时，壮于进者也，故有壮趾之象。以是而往，凶之道也。然阳刚居正，本有其德，故教占者，惟自信其德，以甘穷困，不可有所往，往则凶矣。</p><h3 id="《象》曰-壮于趾-其孚穷也。" tabindex="-1">《象》曰：壮于趾，其孚穷也。 <a class="header-anchor" href="#《象》曰-壮于趾-其孚穷也。" aria-label="Permalink to “《象》曰：壮于趾，其孚穷也。”">​</a></h3><p>既无应援，又卑下无位，故曰穷。当壮进之时，有其德而不能进，进则必凶，乃处穷之时矣，故惟自信其德，以自守可也。是其孚者，不得已也，因穷也，故曰其孚穷。贤人君子，不偶于时，栖止山林者，多是如此。</p><p>九二，贞吉。</p><p>中则无太过，不恃其强而猛于必进，所以此爻贞吉。</p><p>九二以阳刚当大壮之时，居中而不过于壮，盖正而吉者也，故其占如此。</p><h3 id="《象》曰-九二贞吉-以中也。" tabindex="-1">《象》曰：九二贞吉，以中也。 <a class="header-anchor" href="#《象》曰-九二贞吉-以中也。" aria-label="Permalink to “《象》曰：九二贞吉，以中也。”">​</a></h3><p>以中者，居中位也，与解卦得中道，未济中以行正同。中立而不倚强哉矫，九二有焉。</p><p>九三，小人用壮，君子用罔，贞厉。羝羊触藩，羸其角。羸力为切</p><p>罔者无也，言不用也。君子以义理为勇，以非礼弗履为大壮，故不用壮也。羝羊，壮羊也。羸者瘦也，病也。羝羊恃其强壮，乃触其藩，其角出于藩之外，易去而难反，不能用其力，是角之壮者，反为藩所困制而弱病矣，故曰羸其角也。本卦大象兑，中爻为兑，皆羊之象，故诸爻皆以羊言之。震为竹为苇，藩之象也。触藩者，用壮之象也。阳居阳位，故曰贞。羸角者，又贞厉之象也。</p><p>九三过刚不中，又当干体之终，交震动之际，乃纯用血气之强，过于壮者也。然用壮为小人之事，君子以义理为主，岂其所用哉，故圣人戒占者曰，惟小人则用壮，君子则不用也。茍用其壮，虽正亦厉，亦如羊之触藩羸角也，壮其可恃哉。戒之之严，故占中之象又如此。</p><h3 id="《象》曰-小人用壮-君子罔也。" tabindex="-1">《象》曰：小人用壮，君子罔也。 <a class="header-anchor" href="#《象》曰-小人用壮-君子罔也。" aria-label="Permalink to “《象》曰：小人用壮，君子罔也。”">​</a></h3><p>言用壮者，小人之事，君子则无此也。</p><p>九四，贞吉，悔亡。藩决不羸，壮于大舆之輹。</p><p>贞吉悔亡者，惟正则吉，而悔亡也。决，破也，藩决不羸，承上文而言也。三前有四之阻隔，犹有藩焉。四前二阴，则藩决而可前进矣。震为大涂，兑为附决，藩决之象也。輹与辐同，车轮之中干也。车之败，常在折輹，輹壮则车强。四变坤，大舆之象也。壮于大舆之輹，言尚往而可进也。此二句，又贞吉悔亡之象也。</p><p>九四当大壮之时，以阳居阴，不极其刚，前无困阻，而可以尚往矣，故其占中之象如此。</p><h3 id="《象》曰-藩决不羸-尚往也。" tabindex="-1">《象》曰：藩决不羸，尚往也。 <a class="header-anchor" href="#《象》曰-藩决不羸-尚往也。" aria-label="Permalink to “《象》曰：藩决不羸，尚往也。”">​</a></h3><p>尚往者，前无困阻，而可以上进也。</p><p>六五，丧羊于易，无悔。易音亦</p><p>易即埸，田畔也。震为大涂，埸之象也。</p><p>本卦四阳在下，故名大壮，至六五无阳，则丧失其所谓大壮矣。故有丧羊于易之象，既失其壮，则不能前进，仅得无悔而已，故其象占如此。</p><h3 id="《象》曰-丧羊于易-位不当也。" tabindex="-1">《象》曰：丧羊于易，位不当也。 <a class="header-anchor" href="#《象》曰-丧羊于易-位不当也。" aria-label="Permalink to “《象》曰：丧羊于易，位不当也。”">​</a></h3><p>位不当者，以柔居五位也。</p><p>上六，羝羊触藩，不能退，不能遂，无攸利，艰则吉。</p><p>震错巽，为进退，退遂之象也。艰者，处之艰难而不忽慢也。吉者，无攸利者，终得攸利也。六五已丧羊矣，而上六又羝羊触藩者，盖六五以一爻言也。上六则合一卦而言也，三则刚之极，上则动之极，所以爻象皆同。</p><p>上六壮终动极，所以触藩而不能退。然其质本柔，又不能遂其进也，故有触藩不能退遂之象。占者之无攸利可知矣。然犹幸其不刚，而不妄进也。若占者能艰以处之，则得以遂其进而吉矣。</p><h3 id="《象》曰-不能退-不能遂-不详也-艰则吉-咎不长也。" tabindex="-1">《象》曰：不能退，不能遂，不详也;艰则吉，咎不长也。 <a class="header-anchor" href="#《象》曰-不能退-不能遂-不详也-艰则吉-咎不长也。" aria-label="Permalink to “《象》曰：不能退，不能遂，不详也;艰则吉，咎不长也。”">​</a></h3><p>详者，慎密也。不详者，当壮终动极之时，不能度势而行，审几而进也。既详则能艰矣。咎者不能退、不能遂之咎也，惟艰则能详而咎不长矣。心思之艰难，所以能详，识见之详明，所以方艰。</p>',37)])])}const f=e(h,[["render",t]]);export{_ as __pageData,f as default};
